// 簡易的な状態管理と検証ロジック
const useRegistrationForm = () => {
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    password: "",
    confirmPassword: "",
  });
  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [message, setMessage] = useState("");
  const [messageType, setMessageType] = useState(""); // 'success' or 'error'

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
    // 入力時にエラーをクリア
    if (errors[name]) {
      setErrors((prev) => ({ ...prev, [name]: null }));
    }
    setMessage("");
  };

  const validate = () => {
    let newErrors = {};
    if (!formData.name) newErrors.name = "ユーザー名を入力してください。";
    if (!formData.email || !/\S+@\S+\.\S+/.test(formData.email))
      newErrors.email = "有効なメールアドレスを入力してください。";
    if (formData.password.length < 8)
      newErrors.password = "パスワードは8文字以上である必要があります。";
    if (formData.password !== formData.confirmPassword)
      newErrors.confirmPassword = "パスワードが一致しません。";
    return newErrors;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const validationErrors = validate();
    setErrors(validationErrors);

    if (Object.keys(validationErrors).length > 0) {
      setMessageType("error");
      setMessage("フォームにエラーがあります。修正してください。");
      return;
    }

    setIsSubmitting(true);
    setMessage("登録処理中です...");
    setMessageType("info");

    try {
      // 実際にはここで Firebase Auth や API エンドポイントへの POST リクエストを行います
      await new Promise((resolve) => setTimeout(resolve, 1500)); // 擬似的な API 遅延

      console.log("Registration Data:", formData);

      // 成功時のフィードバック
      setMessageType("success");
      setMessage(`ユーザー「${formData.name}」の登録が完了しました！`);
      setFormData({ name: "", email: "", password: "", confirmPassword: "" }); // フォームをクリア
    } catch (error) {
      console.error("Registration failed:", error);
      setMessageType("error");
      setMessage("登録中にエラーが発生しました。もう一度お試しください。");
    } finally {
      setIsSubmitting(false);
    }
  };

  return {
    formData,
    errors,
    isSubmitting,
    message,
    messageType,
    handleChange,
    handleSubmit,
  };
};

// フォームの入力フィールドコンポーネント (Iconコンポーネントをpropsとして受け取る)
const InputField = ({
  Icon,
  name,
  type = "text",
  placeholder,
  value,
  onChange,
  error,
  disabled,
}) => (
  <div className="space-y-1">
    <div className="relative">
      <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none">
        <Icon className="w-5 h-5 text-indigo-400" />
      </div>
      <input
        id={name}
        name={name}
        type={type}
        placeholder={placeholder}
        value={value}
        onChange={onChange}
        disabled={disabled}
        className={`w-full pl-10 pr-4 py-3 border rounded-lg text-gray-800 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-indigo-500 transition duration-150 ${
          error ? "border-red-500" : "border-gray-300"
        } disabled:bg-gray-100`}
      />
    </div>
    {error && <p className="text-xs text-red-500">{error}</p>}
  </div>
);

// メインのサインアップコンポーネント
const App = () => {
  // Next.js App Router でクライアントコンポーネントとして動作させるために必要
  // 実際にご自身のファイルにコピーする際は、この行のコメントアウトを外すか、
  // このコンポーネントをインポートするファイル（page.tsx）の冒頭に記述してください。
  // 'use client';

  const {
    formData,
    errors,
    isSubmitting,
    message,
    messageType,
    handleChange,
    handleSubmit,
  } = useRegistrationForm();

  const getMessageClasses = () => {
    switch (messageType) {
      case "success":
        return "bg-green-100 text-green-800 border-green-400";
      case "error":
        return "bg-red-100 text-red-800 border-red-400";
      case "info":
        return "bg-blue-100 text-blue-800 border-blue-400";
      default:
        return "hidden";
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50 p-4 font-inter">
      <div className="w-full max-w-md bg-white p-6 sm:p-8 rounded-2xl shadow-2xl border border-gray-100">
        <div className="text-center mb-8">
          <LogInIcon className="w-10 h-10 text-indigo-600 mx-auto transform rotate-90" />
          <h1 className="text-3xl font-bold text-gray-900 mt-3">
            新規ユーザー登録
          </h1>
          <p className="text-gray-500 text-sm mt-1">
            アカウントを作成してサービスを始めましょう
          </p>
        </div>

        {message && (
          <div
            className={`p-3 mb-6 rounded-lg border text-sm transition-all duration-300 ${getMessageClasses()}`}
            role="alert"
          >
            {message}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-5">
          <InputField
            Icon={UserIcon}
            name="name"
            placeholder="ユーザー名"
            value={formData.name}
            onChange={handleChange}
            error={errors.name}
            disabled={isSubmitting}
          />
          <InputField
            Icon={MailIcon}
            name="email"
            type="email"
            placeholder="メールアドレス"
            value={formData.email}
            onChange={handleChange}
            error={errors.email}
            disabled={isSubmitting}
          />
          <InputField
            Icon={LockIcon}
            name="password"
            type="password"
            placeholder="パスワード (8文字以上)"
            value={formData.password}
            onChange={handleChange}
            error={errors.password}
            disabled={isSubmitting}
          />
          <InputField
            Icon={LockIcon}
            name="confirmPassword"
            type="password"
            placeholder="パスワード (確認用)"
            value={formData.confirmPassword}
            onChange={handleChange}
            error={errors.confirmPassword}
            disabled={isSubmitting}
          />

          <button
            type="submit"
            disabled={isSubmitting}
            className="w-full flex justify-center items-center py-3 px-4 border border-transparent rounded-lg shadow-md text-base font-medium text-white bg-indigo-600 hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 transition duration-150 disabled:bg-indigo-400 disabled:cursor-not-allowed"
          >
            {isSubmitting ? (
              <>
                <svg
                  className="animate-spin -ml-1 mr-3 h-5 w-5 text-white"
                  xmlns="http://www.w3.org/2000/svg"
                  fill="none"
                  viewBox="0 0 24 24"
                >
                  <circle
                    className="opacity-25"
                    cx="12"
                    cy="12"
                    r="10"
                    stroke="currentColor"
                    strokeWidth="4"
                  ></circle>
                  <path
                    className="opacity-75"
                    fill="currentColor"
                    d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                  ></path>
                </svg>
                登録中...
              </>
            ) : (
              "登録する"
            )}
          </button>
        </form>

        <div className="mt-6 text-center">
          <a
            href="#"
            className="text-sm text-indigo-600 hover:text-indigo-500 font-medium"
          >
            すでにアカウントをお持ちですか？サインインはこちら
          </a>
        </div>
      </div>
    </div>
  );
};

export default App;
